import styled from "styled-components";

export const RegisterWrapper = styled.main`
    width: 100%;
    height: 100vh;

    position: relative;

    display: flex;
    align-items: center;
    justify-content: center;

` 
export const BodyRegisterContainer= styled.div`
    top:0;
    left:0;
    width: 100%;
    height: 50vh;
   
    position:absolute;
   
`
